#include "../Player.h"
#include <string>
std::string breakdown(const Player& player) {
    const Scorecard& card = player.scorecard();
    return std::to_string(card.total()) + " + " + std::to_string(card.upperBonus())
        + " + " + std::to_string(card.yahtzeeBonus()) + " = " + std::to_string(player.finalScore());
}

