#include <vector>
#include <cstddef>
bool takeRoll(const std::vector<int>& sequence, std::size_t& cursor, int& face) {
    if (cursor >= sequence.size()) return false;
    const int candidate = sequence[cursor];
    if (candidate < 1 || candidate > 6) return false;
    face = candidate; ++cursor; return true;
}

