#include <string>
#include <sstream>
#include <vector>
#include <cstddef>
bool strictKeepers(const std::string& line, std::size_t count, std::vector<bool>& output) {
    std::istringstream words(line);
    std::string token;
    std::vector<bool> candidate(count, false);
    bool any = false;
    while (words >> token) {
        if (token == "a" || token == "A") {
            if (any || (words >> token)) return false;
            candidate.assign(count, true); output = candidate; return true;
        }
        std::istringstream number(token); int position = 0; char extra;
        if (!(number >> position) || (number >> extra) || position < 1
            || static_cast<std::size_t>(position) > count) return false;
        candidate[static_cast<std::size_t>(position) - 1] = true; any = true;
    }
    output = candidate; return true;
}

